module parallel2serial (
    // Inputs and Outputs defined in the order specified in the XML file
    input           clk,
    input           rst_n,
    input   [3:0]   d,
    output          valid_out,
    output          dout
);
reg     [3:0]   data;
reg             valid;
reg     [1:0]   cnt;
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        cnt <= 'd0;
        valid <= 1'd0;
        data <= 4'd0;
    end else begin
        if (cnt == 2'd3) begin
            data <= d;
            cnt <= 2'd0;
            valid <= 1'd1;
        end else begin
            cnt <= cnt + 2'd1;
            valid <= 1'd0;
            data <= {data[2:0], data[3]};
        end
    end
end
// Assign dout to the MSB of the shift register
assign dout = data[3];
// Assign valid_out to the valid register
assign valid_out = valid;
endmodule
